{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Mithramycin, a large aromatic polyketide glycoside, showed a CSF:plasma ratio of only 0.12 in monkeys with little brain distribution, indicating that highly glycosylated polyketide natural products have poor CNS access; this transfers to the query's anthracycline glycoside scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Digitoxin, a cardiac glycoside with multiple sugar residues, exhibited a very low CSF/plasma ratio (0.01-0.03) in dogs, supporting poor BBB penetration for large glycoside natural products similar in size and polarity to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Vertilmicin, a polar aminoglycoside, had the lowest brain concentration among all tissues in rats, demonstrating that molecules combining multiple hydroxyl groups and aminosugar-like features have very low BBB permeation; the query contains an aminosugar and many polar hydroxyls.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "DX-52-1, a complex natural product, showed a brain-to-blood ratio of about 0.02 in mice, indicating that large, complex molecules with multiple polar functionalities are generally poor BBB penetrants, consistent with the query's properties.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "CMT-3, a lipophilic tetracycline, accumulated in rat brain at 4 µg/g and was labeled permeable, showing that some fused polyketide antibiotics can cross the BBB; however, the query is larger and more heavily glycosylated, limiting the transferability of this positive result.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C07"],
      "claim": "Emodin-8-O-β-D-glucoside distributed into rat brain in a dose-dependent manner, suggesting that some glycosylated anthraquinones can penetrate the BBB; this provides weak contradictory evidence, but the effect was enhanced under ischemia and the compound is much smaller and less polar than the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a large, polyhydroxylated anthracycline glycoside with an aminosugar. Direct evidence from related glycosides and aminoglycosides (mithramycin, digitoxin, vertilmicin, DX-52-1) consistently indicates poor CNS penetration, while the permeable examples are structurally more distant or show only weak/condition-dependent brain distribution. Therefore the query is predicted to lack meaningful CNS access.",
  "evidence_gaps": [
    "No direct brain, CSF, or plasma pharmacokinetic data exist for the query molecule itself.",
    "Morgan similarities to the evidence molecules are low (0.19-0.27), so structural transfer is approximate.",
    "Efflux transporter involvement (e.g., P-gp) was not directly measured for the query or most analogues.",
    "The positive BBB-permeable examples are structurally dissimilar and may not represent the query's glycoside-dominated polarity."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

